CREATE TABLE case_time_entries(tenant_id uuid NOT NULL,case_id uuid NOT NULL,id uuid NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version BETWEEN 1 AND 100),started_at timestamptz NOT NULL,minutes integer NOT NULL CHECK(minutes BETWEEN 1 AND 1440),description text NOT NULL CHECK(length(btrim(description)) BETWEEN 3 AND 2000),billable boolean NOT NULL,request_hash char(64) NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),created_by uuid NOT NULL REFERENCES users(id),created_by_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,case_id,id),FOREIGN KEY(tenant_id,case_id) REFERENCES cases(tenant_id,id));
CREATE TABLE case_time_entry_revisions(tenant_id uuid NOT NULL,case_id uuid NOT NULL,entry_id uuid NOT NULL,version integer NOT NULL CHECK(version BETWEEN 1 AND 100),started_at timestamptz NOT NULL,minutes integer NOT NULL CHECK(minutes BETWEEN 1 AND 1440),description text NOT NULL CHECK(length(btrim(description)) BETWEEN 3 AND 2000),billable boolean NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 3 AND 2000),actor_id uuid NOT NULL REFERENCES users(id),actor_name text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,case_id,entry_id,version),FOREIGN KEY(tenant_id,case_id,entry_id) REFERENCES case_time_entries(tenant_id,case_id,id));
CREATE INDEX case_time_entries_case_started ON case_time_entries(tenant_id,case_id,started_at DESC,id DESC);
CREATE TRIGGER case_time_history_immutable BEFORE UPDATE OR DELETE ON case_time_entry_revisions FOR EACH ROW EXECUTE FUNCTION reject_append_only_mutation();
CREATE TRIGGER case_time_no_delete BEFORE DELETE ON case_time_entries FOR EACH ROW EXECUTE FUNCTION reject_append_only_mutation();
GRANT SELECT,INSERT ON case_time_entries,case_time_entry_revisions TO inveos_app;GRANT UPDATE(version,started_at,minutes,description,billable,updated_at) ON case_time_entries TO inveos_app;